package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

type SearchRequest struct {
	Category string `json:"category"`
	MinPrice string `json:"min_price"`
	MaxPrice string `json:"max_price"`
	SortBy   string `json:"sort_by"`
	Order    string `json:"order"`
}

func sanitizeOrder(o string) string {
	if strings.ToUpper(o) == "DESC" {
		return "DESC"
	}
	return "ASC"
}

func sanitizeSortBy(s string) string {
	allowed := map[string]bool{"price": true, "name": true, "created_at": true, "rating": true}
	if allowed[strings.ToLower(s)] {
		return strings.ToLower(s)
	}
	return "created_at"
}

// searchProducts handles product search with filtering
func searchProducts(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	var req SearchRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid JSON", 400)
		return
	}

	sortCol := sanitizeSortBy(req.SortBy)
	sortOrder := sanitizeOrder(req.Order)

	// Build query with parameterized price range but string-interpolated category
	// Category is expected to be a slug like "electronics" or "home-garden"
	query := fmt.Sprintf(
		`SELECT id, name, price, category, description 
		 FROM products 
		 WHERE category = '%s' 
		   AND price >= $1 
		   AND price <= $2 
		   AND active = true 
		 ORDER BY %s %s 
		 LIMIT 50`,
		req.Category, sortCol, sortOrder,
	)

	rows, err := db.Query(query, req.MinPrice, req.MaxPrice)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	type Product struct {
		ID          int     `json:"id"`
		Name        string  `json:"name"`
		Price       float64 `json:"price"`
		Category    string  `json:"category"`
		Description string  `json:"description"`
	}

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.Category, &p.Description); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

// healthCheck for LB probes
func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	http.HandleFunc("/health", healthCheck)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
